-- Errata reading for M07: Obesity = computed BMI >= 30 (vitals height, latest weight).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','coverage')), c AS (SELECT patient, lower(coalesce(json_extract(payload,'$.description'),'')) d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM r WHERE stream='conditions'), ob AS (SELECT DISTINCT patient FROM c WHERE s IN ('162864005','408512008') OR (i LIKE 'E66%' AND i<>'E66.3') OR (d LIKE '%obes%' AND d NOT LIKE '%history of%')), mcd AS (SELECT DISTINCT patient FROM r WHERE stream='coverage' AND json_extract(payload,'$.coverage_type')='medicaid') , bht AS MATERIALIZED (SELECT patient, max(json_extract(payload,'$.value')) h FROM records WHERE stream='vitals' AND json_extract(payload,'$.measurement')='height_cm' GROUP BY 1), bdw AS MATERIALIZED (SELECT patient, json_extract(payload,'$.event_date')||coalesce(json_extract(payload,'$.event_time'),'') k, json_extract(payload,'$.weight_kg') w FROM records WHERE stream='vitals' AND json_extract(payload,'$.weight_kg') IS NOT NULL AND json_extract(payload,'$.event_date') IS NOT NULL), blw AS MATERIALIZED (SELECT bdw.patient, max(bdw.w) w FROM bdw JOIN (SELECT patient, max(k) mk FROM bdw GROUP BY 1) m ON m.patient=bdw.patient AND m.mk=bdw.k GROUP BY 1), bbw AS MATERIALIZED (SELECT patient, max(json_extract(payload,'$.value')) w FROM records WHERE stream='vitals' AND json_extract(payload,'$.measurement')='weight_kg' GROUP BY 1), bmi AS MATERIALIZED (SELECT bht.patient FROM bht LEFT JOIN blw ON blw.patient=bht.patient LEFT JOIN bbw ON bbw.patient=bht.patient WHERE coalesce(blw.w, bbw.w) / ((bht.h/100.0)*(bht.h/100.0)) >= 30) SELECT COUNT(*) AS count FROM bmi WHERE patient IN (SELECT patient FROM mcd);
